-- ============================================================
-- Southern Precision Partners — seed prospect pipeline (Landbase SC export)
-- Applied to the dedicated Supabase project `southern-precision-partners`
-- (ref yscxrvuwwfpjuciuawcv). Idempotent: INSERT ... ON CONFLICT DO NOTHING
-- on the natural keys (company_key / contact_key), so re-running is safe.
--
-- Source: two CSVs uploaded 2026-07-22 —
--   "Landbase - Atlanta roof replacement pros export" (companies) and
--   "…export_1" (decision-maker contacts). Despite the "Atlanta" filename the
--   records are South Carolina construction/remodeling firms — the exact Pro
--   buyer for the SC expansion. 213 companies, 369 contacts.
--
-- fit_score is a transparent heuristic (revenue band + tile/remodel keyword
-- fit + decision-maker seniority + reachability), NOT vendor-supplied — the
-- export's own "Fit"/"Relevance" columns came back empty.
--
-- The final UPDATE links a prospect to an existing customer where its
-- normalized name prefix-matches a (truncated) customer name_key. It writes
-- ONLY to prospect_companies — never to customers — so existing customer
-- records are untouched; the match is a reviewable enrichment candidate.
-- ============================================================

-- ---------- companies ----------
insert into public.prospect_companies (
  company_key, name, website, industry, street, city, state, zip, region, employees, revenue, revenue_range, size_range, email, phone, fit_score, fit_evidence
) values
